steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{
      issue(identifier: \"ENG-5\") {
        id
        identifier
        title
        assignee {
          id
          name
          email
        }
      }
      users(first: 100) {
        nodes {
          id
          name
          email
        }
      }
    }"
  }'
